const money=(v:number|null,compact=false)=>v===null||Number.isNaN(v)?"Not Available":new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0,notation:compact?"compact":"standard"}).format(v);
const num=(v:number|null,d=0)=>v===null||Number.isNaN(v)?"Not Available":v.toFixed(d);
const median=(xs:number[])=>{if(!xs.length)return null;const a=[...xs].sort((x,y)=>x-y),m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2};
const avg=(xs:number[])=>xs.length?xs.reduce((s,v)=>s+v,0)/xs.length:null;
const pct=(v:number|null)=>v===null?"Not Available":`${(v*100).toFixed(1)}%`;

type Subject={address:string;arv:number;propertyType:"Single Family"|"Townhome";beds:number;baths:number;sqft:number;pool:boolean;garage:number;year:number;maxRadius:number;arvLow:number;arvHigh:number};
