    const active=set.filter(c=>c.status==="Active"),pending=set.filter(c=>c.status==="Pending"),auc=set.filter(c=>c.status==="Active Under Contract"),expired=set.filter(c=>c.status==="Expired"),withdrawn=set.filter(c=>c.status==="Withdrawn"),inventory=periods.map(p=>p.velocity?active.length/p.velocity:null),near=(c:Comp)=>{const p=c.soldPrice??c.finalList;return p!==null&&p>=subject.arvLow&&p<=subject.arvHigh},soldNear=set.filter(c=>c.status==="Sold"&&near(c)),activeNear=active.filter(near),pendingNear=[...pending,...auc].filter(near),nearDom=soldNear.flatMap(c=>c.dom===null?[]:[c.dom]),nearRatios=soldNear.flatMap(c=>c.soldPrice===null||c.originalList===null?[]:[c.soldPrice/c.originalList]),renDom=soldNear.filter(c=>c.condition==="Renovated"||c.condition==="Updated").flatMap(c=>c.dom===null?[]:[c.dom]),base=Math.round(median(renDom)??median(nearDom)??45),expectedLow=Math.max(10,Math.floor((base-8)/5)*5),expectedHigh=Math.ceil((base+12)/5)*5;
    const arvComps=set.filter(c=>c.status==="Sold"&&(c.condition==="Renovated"||c.condition==="Updated")).map(c=>({...c,s:score(c,subject,"arv")})).sort((x,y)=>y.s-x.s).slice(0,6),weighted=arvComps.length?arvComps.reduce((s,c)=>s+(c.soldPrice??0)*c.s,0)/arvComps.reduce((s,c)=>s+c.s,0):null,arvSupported=!!weighted&&Math.abs(subject.arv-weighted)/weighted<=.05&&soldNear.length>=3;
    const recent=inventory[0]??99,medDom=median(nearDom)??99,reduction=soldNear.length?soldNear.filter(c=>c.reduced).length/soldNear.length:1,pendingSignal=pendingNear.length/Math.max(1,activeNear.length);const ls=(recent<=2?4:recent<=3.5?3:recent<=5?2:recent<=7?1:0)+(medDom<=30?3:medDom<=45?2:medDom<=65?1:0)+(pendingSignal>=.75?2:pendingSignal>=.35?1:0)+(reduction<=.35?1:0);const liquidity=ls>=9?"Very Strong":ls>=7?"Strong":ls>=5?"Moderate":ls>=3?"Weak":"High Risk";
