    const display=set.map(c=>({...c,arvScore:score(c,subject,"arv"),velocityScore:score(c,subject,"velocity")})).sort((x,y)=>sortBy==="distance"?x.distance-y.distance:sortBy==="saleDate"?(x.daysAgo??999)-(y.daysAgo??999):sortBy==="dom"?(x.dom??999)-(y.dom??999):sortBy==="ppsf"?((y.soldPrice??y.finalList??0)/y.sqft)-((x.soldPrice??x.finalList??0)/x.sqft):y.arvScore-x.arvScore);
